ANCLA_INSERCION = 'st.set_page_config('


def main():
    if len(sys.argv) < 2:
        print("Uso: python aplicar_logo.py app.py")
        sys.exit(1)

    ruta = sys.argv[1]
    with open(ruta, encoding='utf-8') as f:
        codigo = f.read()

    if ANCLA_INSERCION not in codigo:
        print(f"⚠️  No encontré '{ANCLA_INSERCION}' en el archivo — no pude insertar las constantes del logo.")
        sys.exit(1)

    codigo = codigo.replace(ANCLA_INSERCION, CONSTANTES + ANCLA_INSERCION, 1)

    ok, fallidos = 0, []
    for nombre, viejo, nuevo in REEMPLAZOS:
        if viejo in codigo:
            codigo = codigo.replace(viejo, nuevo, 1)
            ok += 1
            print(f"✅ Reemplazado: {nombre}")
        else:
            fallidos.append(nombre)
            print(f"⚠️  NO encontrado (revisar a mano): {nombre}")

    salida = ruta.rsplit('.', 1)[0] + '_con_logo.py'
    with open(salida, 'w', encoding='utf-8') as f:
        f.write(codigo)

    print(f"\n{ok}/{len(REEMPLAZOS)} reemplazos aplicados.")
    print(f"Archivo generado: {salida}")
    if fallidos:
        print("\nPara los que fallaron, revisá si tu código tiene espacios/saltos de línea")
        print("distintos al original en esa sección — puede que lo hayas editado después.")


if __name__ == '__main__':
    main()
